export const MEMORY_EFFECT_ACTIONS = [
  "memory_update",
  "memory_forget",
  "memory_strengthen",
] as const;

export type MemoryEffectAction = (typeof MEMORY_EFFECT_ACTIONS)[number];
export type MemoryEffectOutcome = "applied" | "not_applied" | "unknown";

export type MemoryEffectActor = {
  sessionKey: string;
  runId: string;
  attemptIndex: number;
  modelCallIndex: number;
};

export type MemoryEffectInvocation = {
  toolCallId: string;
  toolName: string;
  resource: string;
  action: string;
};

export type MemoryEffectStage1Context = {
  actor: MemoryEffectActor;
  effect: MemoryEffectInvocation;
};

/** Digest-only proposal. Memory text and tool arguments are intentionally absent. */
export type MemoryEffectProposal = {
  domain: "runtime.memory";
  action: MemoryEffectAction;
  factId: string;
  newFactId?: string;
};

export type MemoryEffectReceipt = {
  effectId: string;
  requestId: string;
  actor: MemoryEffectActor;
  domain: "runtime.memory";
  action: MemoryEffectAction;
  proposal: MemoryEffectProposal;
  stage1Context: MemoryEffectStage1Context;
  outcome: MemoryEffectOutcome;
  idempotencyKey: string;
  contentDigest: string;
};

/**
 * Structural adapter for the RC-04 EffectReceiptStore. Keeping this interface
 * structural lets memory use the existing store without introducing another
 * persistence implementation.
 */
export type EffectReceiptStoreLike = {
  appendEffectReceipt?: (receipt: MemoryEffectReceipt) => unknown;
  appendReceipt?: (receipt: MemoryEffectReceipt) => unknown;
  append?: (receipt: MemoryEffectReceipt) => unknown;
  record?: (receipt: MemoryEffectReceipt) => unknown;
};

export type MemoryEffectReceiptSink = EffectReceiptStoreLike;

export type MemoryEffectReceiptContext = {
  actor: MemoryEffectActor;
  effect: MemoryEffectInvocation;
  receiptSink?: EffectReceiptStoreLike;
};

export type MemoryEffectReceiptRequest = {
  action: MemoryEffectAction;
  factId: string;
  newFactId?: string;
  outcome: MemoryEffectOutcome;
};

export type MemoryEffectReceiptResult = {
  effectId: string;
  requestId: string;
  idempotencyKey: string;
  duplicate: boolean;
};

function encodePart(value: string): string {
  return encodeURIComponent(value);
}

/** Stable, non-cryptographic digest used only to identify receipt content. */
export function memoryEffectContentDigest(value: unknown): string {
  const text = stableStringify(value);
  let hash = 2166136261;
  for (let index = 0; index < text.length; index += 1) {
    hash ^= text.charCodeAt(index);
    hash = Math.imul(hash, 16777619);
  }
  return `fnv1a32:${(hash >>> 0).toString(16).padStart(8, "0")}`;
}

function stableStringify(value: unknown): string {
  if (value === null || typeof value !== "object") return JSON.stringify(value);
  if (Array.isArray(value)) return `[${value.map(stableStringify).join(",")}]`;
  const record = value as Record<string, unknown>;
  return `{${Object.keys(record).sort().map((key) => `${JSON.stringify(key)}:${stableStringify(record[key])}`).join(",")}}`;
}

/**
 * Idempotency is derived from intent, never from outcome. Replaying the same
 * tool invocation therefore targets the same receipt.
 */
export function deriveMemoryEffectIdempotencyKey(
  action: MemoryEffectAction,
  factId: string,
  actor: Pick<MemoryEffectActor, "sessionKey" | "runId">,
  toolCallId: string,
): string {
  return [
    "runtime.memory",
    action,
    factId,
    actor.sessionKey,
    actor.runId,
    toolCallId,
  ].map(encodePart).join(":");
}

export function buildMemoryEffectReceipt(
  request: MemoryEffectReceiptRequest,
  context: MemoryEffectReceiptContext,
): MemoryEffectReceipt {
  const proposal: MemoryEffectProposal = {
    domain: "runtime.memory",
    action: request.action,
    factId: request.factId,
    ...(request.newFactId !== undefined ? { newFactId: request.newFactId } : {}),
  };
  const idempotencyKey = deriveMemoryEffectIdempotencyKey(
    request.action,
    request.factId,
    context.actor,
    context.effect.toolCallId,
  );
  const contentDigest = memoryEffectContentDigest({
    proposal,
    actor: context.actor,
    effect: context.effect,
  });
  return {
    effectId: `memory-effect:${idempotencyKey}`,
    requestId: context.effect.toolCallId,
    actor: context.actor,
    domain: proposal.domain,
    action: proposal.action,
    proposal,
    stage1Context: {
      actor: context.actor,
      effect: context.effect,
    },
    outcome: request.outcome,
    idempotencyKey,
    contentDigest,
  };
}

function appendToStore(
  store: EffectReceiptStoreLike,
  receipt: MemoryEffectReceipt,
): { duplicate: boolean } {
  const append = store.appendEffectReceipt ?? store.appendReceipt ?? store.append ?? store.record;
  if (append === undefined) throw new Error("Effect receipt store has no append operation");
  const result = append.call(store, receipt) as unknown;
  if (result !== null && typeof result === "object") {
    const duplicate = (result as { duplicate?: unknown }).duplicate;
    return { duplicate: duplicate === true };
  }
  return { duplicate: false };
}

/**
 * Receipt emission is deliberately fail-open: a missing or faulty sink cannot
 * change the result of the memory operation.
 */
export function emitMemoryEffectReceipt(
  request: MemoryEffectReceiptRequest,
  context: MemoryEffectReceiptContext,
): MemoryEffectReceiptResult | undefined {
  const receipt = buildMemoryEffectReceipt(request, context);
  try {
    const result = context.receiptSink
      ? appendToStore(context.receiptSink, receipt)
      : { duplicate: false };
    return {
      effectId: receipt.effectId,
      requestId: receipt.requestId,
      idempotencyKey: receipt.idempotencyKey,
      duplicate: result.duplicate,
    };
  } catch {
    return undefined;
  }
}

export function isMemoryEffectProposal(value: unknown): value is MemoryEffectProposal {
  if (value === null || typeof value !== "object" || Array.isArray(value)) return false;
  const record = value as Record<string, unknown>;
  return (
    record.domain === "runtime.memory" &&
    typeof record.action === "string" &&
    (MEMORY_EFFECT_ACTIONS as readonly string[]).includes(record.action) &&
    typeof record.factId === "string" &&
    (record.newFactId === undefined || typeof record.newFactId === "string") &&
    !("objectSummary" in record) &&
    !("subject" in record) &&
    !("predicate" in record) &&
    !("content" in record)
