    return { ok: true, tool: "memory_update", message: `Fact ${factId} superseded by ${newFactId}.`, data: { oldFactId: factId, newFactId, updatedFields: { ...(subject !== existing.subject ? { subject } : {}), ...(predicate !== existing.predicate ? { predicate } : {}), ...(objectSummary !== existing.objectSummary ? { objectSummary } : {}), ...(confidence !== existing.confidence ? { confidence } : {}) } } };
  },
};

export const memoryForgetTool: MemorySelfEditTool = {
  name: "memory_forget", description: "Invalidate a runtime memory fact.", parameters: { type: "object", properties: { factId: { type: "string" }, reason: { type: "string", enum: ["retracted", "human_rejected"] } }, required: ["factId"] },
  execute(args, context) {
    const factId = stringArg(args, "factId"); if (factId === undefined) return { ok: false, tool: "memory_forget", message: "Missing required argument: factId." };
    const existing = context.store.getFactById(factId); if (existing === undefined) { emit(context, "memory_forget", "memory_forget", factId, "not_applied"); return { ok: false, tool: "memory_forget", message: `Fact not found: ${factId}.` }; }
    const now = resolveNow(context); const reason = (stringArg(args, "reason") as "retracted" | "human_rejected" | undefined) ?? "retracted";
    const sourceEpisodeRefs = existing.sourceEpisodeRefs.length ? existing.sourceEpisodeRefs.map(cloneEpisode) : [{ episodeId: "memory_self_edit", taskId: context.taskId ?? "memory_self_edit", kind: "human_confirmation" as const, idempotencyKey: `memory_self_edit_forget:${factId}:${now}`, reference_time: now }];
    const sanitized = sanitizeRuntimeMemoryInvalidationProposal({ schemaVersion: 1, invalidationId: `invalidation_${factId}_${now}`, factId, reason, invalid_at: now, reference_time: now, proposedBy: "human_confirmation", verificationStatus: "human_approved", sourceEpisodeRefs, evidenceRefs: [evidence(now)] });
    if (!sanitized.accepted) { emit(context, "memory_forget", "memory_forget", factId, "not_applied"); return { ok: false, tool: "memory_forget", message: `Failed to create invalidation: ${sanitized.message}.` }; }
    const result = persistInvalidation(context, sanitized.value); if (!result.ok) { emit(context, "memory_forget", "memory_forget", factId, "not_applied"); return { ok: false, tool: "memory_forget", message: `Failed to persist invalidation: ${result.message}.` }; }
    emit(context, "memory_forget", "memory_forget", factId, "applied"); return { ok: true, tool: "memory_forget", message: `Fact ${factId} forgotten (reason: ${reason}).`, data: { factId, reason } };
  },
};

export const memoryStrengthenTool: MemorySelfEditTool = {
  name: "memory_strengthen", description: "Record a usage access for a runtime memory fact.", parameters: { type: "object", properties: { factId: { type: "string" } }, required: ["factId"] },
  execute(args, context) {
    const factId = stringArg(args, "factId"); if (factId === undefined) return { ok: false, tool: "memory_strengthen", message: "Missing required argument: factId." };
    const existing = context.store.getFactById(factId); if (existing === undefined) { emit(context, "memory_strengthen", "memory_strengthen", factId, "not_applied"); return { ok: false, tool: "memory_strengthen", message: `Fact not found: ${factId}.` }; }
    if (context.persistence !== undefined) {
      const result = context.persistence.recordFactAccess(factId); if (result.status !== "persisted") { emit(context, "memory_strengthen", "memory_strengthen", factId, "not_applied"); return { ok: false, tool: "memory_strengthen", message: `Failed to persist usage access: ${result.status === "rejected" ? result.message : `persistence skipped (${result.reason})`}` }; }
      context.store.recordFactAccess(factId); emit(context, "memory_strengthen", "memory_strengthen", factId, "applied"); return { ok: true, tool: "memory_strengthen", message: `Fact ${factId} strengthened (usage count: ${result.accessCount}).`, data: { factId, usageCount: result.accessCount } };
    }
    context.store.recordFactAccess(factId); const stat = context.store.getUsageStats().find((item) => item.factId === factId); const count = stat?.count ?? 0; emit(context, "memory_strengthen", "memory_strengthen", factId, "applied"); return { ok: true, tool: "memory_strengthen", message: `Fact ${factId} strengthened (usage count: ${count}).`, data: { factId, usageCount: count } };
  },
};

export const memoryFindRelatedTool: MemorySelfEditTool = {
  name: "memory_find_related", description: "Find facts related to a given fact.", parameters: { type: "object", properties: { factId: { type: "string" }, relationType: { type: "string" }, hops: { type: "number" }, limit: { type: "number" } }, required: ["factId"] },
  execute(args, context) {
    const factId = stringArg(args, "factId"); if (factId === undefined) return { ok: false, tool: "memory_find_related", message: "Missing required argument: factId." };
    if (context.store.getFactById(factId) === undefined) return { ok: false, tool: "memory_find_related", message: `Fact not found: ${factId}.` };
    const hops = Math.max(1, Math.min(2, numberArg(args, "hops") ?? 1)); const limit = Math.max(1, Math.min(20, numberArg(args, "limit") ?? 10)); const visited = new Set([factId]); const relations: RuntimeMemoryFactRelation[] = []; let frontier = [factId];
    for (let hop = 0; hop < hops; hop += 1) { const next: string[] = []; for (const id of frontier) { const all = [...context.store.queryRelations(id), ...context.store.queryReverseRelations(id)]; for (const relation of all) { relations.push(relation); const other = relation.sourceFactId === id ? relation.targetFactId : relation.sourceFactId; if (!visited.has(other)) { visited.add(other); next.push(other); } } } frontier = next; }
    const facts = [...visited].filter((id) => id !== factId).slice(0, limit).map((id) => context.store.getFactById(id)).filter((fact): fact is NonNullable<typeof fact> => fact !== undefined); const unique = relations.filter((relation, index) => relations.findIndex((item) => item.relationId === relation.relationId) === index);
    return { ok: true, tool: "memory_find_related", message: `Found ${facts.length} related fact(s) within ${hops} hop(s).`, data: { facts: facts.map((fact) => ({ factId: fact.factId, subject: fact.subject, predicate: fact.predicate, objectSummary: fact.objectSummary, verificationStatus: fact.verificationStatus, memoryType: fact.memoryType, valid_at: fact.valid_at })), relations: unique.map((relation) => ({ relationId: relation.relationId, sourceFactId: relation.sourceFactId, targetFactId: relation.targetFactId, relationType: relation.relationType, confidence: relation.confidence })), hops } };
  },
};

export const MEMORY_SELF_EDIT_TOOLS: readonly MemorySelfEditTool[] = [memoryRecallTool, memoryUpdateTool, memoryForgetTool, memoryStrengthenTool, memoryFindRelatedTool];
export function getMemorySelfEditTool(name: MemorySelfEditToolName): MemorySelfEditTool | undefined { return MEMORY_SELF_EDIT_TOOLS.find((tool) => tool.name === name); }
export function executeMemorySelfEditTool(name: MemorySelfEditToolName, args: unknown, context: MemorySelfEditToolContext): Promise<MemorySelfEditToolResult> | MemorySelfEditToolResult { const tool = getMemorySelfEditTool(name); return tool === undefined ? Promise.resolve({ ok: false, tool: name, message: `Unknown tool: ${name}.` }) : tool.execute(args, context); }
"},{"path":"harness/specs/tasks/harness-gap-memory-effect-receipt.md","content":"# S06 Memory effect receipt contract

## Scope

Runtime memory writes (`memory_update`, `memory_forget`, and `memory_strengthen`) emit digest-only receipts through the existing RC-04 `EffectReceiptStore`. No second effect store or migration is introduced.

## Receipt contract

- `effectId` and `requestId` identify the effect and originating tool call.
- `actor` records `sessionKey`, `runId`, `attemptIndex`, and `modelCallIndex`.
- `stage1Context.effect` records `toolCallId`, `toolName`, `resource`, and `action`.
- `proposal` contains only `domain`, `action`, `factId`, and optional `newFactId`.
- Memory subjects, predicates, object summaries, tool arguments, and credentials are excluded.

## Idempotency

The idempotency key is derived from action, fact ID, session key, run ID, and tool-call ID. It does not include outcome. Replaying an identical intent therefore appends no duplicate effect.

## Outcomes

- `applied`: the complete write succeeded.
- `not_applied`: failure occurred before any part of the write was persisted.
- `unknown`: a partial write occurred, such as appending the replacement fact before invalidation or relation persistence fails.

Receipt emission is fail-open: a missing sink or a sink exception must not fail or block the memory write.

## Validation

Targeted tests cover digest-only proposals, actor/effect context, intent idempotency, duplicate replay, all three outcomes, partial-write uncertainty, and fail-open behavior. Runtime-core type checking and scoped lint must pass. Harness validation, dry-run, communications replay/compare, credential scan, and SHA256SUMS read-back complete without side effects in implementation.
"},{"path":"docs/dev/harness-gap-closure/s06-memory-effect-receipt.md","content":"# S06 — Runtime memory effect receipts

## Decision

Memory self-edit writes use the existing RC-04 effect-receipt persistence path. The runtime receives that store through `MemorySelfEditToolContext.effectReceiptStore`; it does not own or create another effect store.

## Privacy and traceability

Receipts are digest-only. The proposal identifies the memory domain, action, affected fact, and optional replacement fact, but never includes memory text. Stage-one context carries the actor identity and the effect/tool invocation needed for audit.

## Replay behavior

The intent idempotency key is independent of the result:

`action + factId + sessionKey + runId + toolCallId`

Consequently, replaying the same tool intent produces the same receipt identity and is recorded as a duplicate by the RC-04 append-only store rather than creating another effect.

## Result semantics

A completed operation is `applied`. A failure before persistence is `not_applied`. If any write has already completed before a later step fails, the receipt is `unknown`; the runtime must not claim that the complete operation was applied.

Receipt generation and append are best effort. Missing receipt infrastructure and receipt-store exceptions are swallowed so observability cannot prevent a memory write.

## Operational checks

1. Run targeted memory effect-receipt tests.
2. Run runtime-core TypeScript validation.
3. Run scoped lint.
4. Validate and dry-run the harness task.
5. Run communications replay/compare.
6. Scan candidate files for credentials (expected zero findings).
7. Read back `SHA256SUMS` and verify the scoped files.
"}]}

