  return (
    isEvidenceRefType(value.type) &&
    isNonEmptyString(value.ref) &&
    isOptionalString(value.label) &&
    isOptionalString(value.summary) &&
    (value.metadata === undefined || isRuntimeCoreJsonObject(value.metadata))
  );
